/* ============================================================================
MSBF M1.16 — Positive Validation
Program : 119_msbf_m1_16_acquisition_foundations_validation_v0_2R1.sql
Version : v0.2R3
Purpose : Validate governance, source/campaign/funnel evidence, attribution,
          cost allocation, M1.14 overlap, companion contract, archive,
          integrated consumption, hashes, and stage boundaries.
Inputs  : Committed M1.16 physical outputs from Program 118.
Outputs : One filterable 112-row result set; persisted positive evidence;
          M1_16_VALIDATED only when every control passes.
Safety  : No business blueprint regeneration. Physical fields are reconstructed
          independently. Result table survives commit in the same DBeaver session.
============================================================================ */
BEGIN;
SET LOCAL lock_timeout='10s';
SET LOCAL statement_timeout='15min';
SET LOCAL work_mem='64MB';
SET LOCAL jit=off;


DROP TABLE IF EXISTS _m1_16_vctx;
CREATE TEMP TABLE _m1_16_vctx ON COMMIT DROP AS
SELECT
 r.run_id,r.run_code,r.run_version,r.run_status,r.population_id,r.as_of_date,
 r.parameter_snapshot_hash,r.profile_snapshot_hash,r.source_snapshot_hash,
 c.contract_code,c.contract_version,c.schema_version,c.methodology_version,
 c.contract_status,c.scenario_set_id,c.source_m1_15_contract_code,
 c.source_m1_15_contract_version,c.source_m1_15_schema_version,
 c.source_m1_15_combined_hash,c.source_m1_14_combined_hash,c.policy_configuration_hash,
 c.source_profile_row_count,c.campaign_row_count,c.funnel_row_count,c.cost_ledger_row_count,
 c.touchpoint_row_count,c.attribution_row_count,c.cost_snapshot_row_count,c.component_row_count,
 c.latest_row_count,c.archive_row_count,c.integrated_view_row_count,
 c.source_profile_set_hash,c.campaign_set_hash,c.funnel_set_hash,c.cost_ledger_set_hash,
 c.touchpoint_set_hash,c.attribution_set_hash,c.cost_snapshot_set_hash,c.component_set_hash,
 c.latest_set_hash,c.archive_set_hash,c.contract_set_hash,c.combined_set_hash,c.contract_row_hash
FROM msbf_ctl.run_registry r
JOIN msbf_ctl.m1_16_acquisition_contract_registry c ON c.module1_run_id=r.run_id
WHERE r.run_code='M1_V0_2_BASELINE_BUILD' AND r.run_version=1
  AND c.contract_code='M1_ACQUISITION_CONSUMPTION' AND c.contract_version=1;
CREATE UNIQUE INDEX ON _m1_16_vctx(run_id);

DROP TABLE IF EXISTS _m1_16_vhashes;
CREATE TEMP TABLE _m1_16_vhashes ON COMMIT DROP AS
WITH h AS(
 SELECT
  (SELECT md5(string_agg('SOURCE|'||acquisition_source_code||'|'||row_hash,'||' ORDER BY acquisition_source_code)) FROM msbf_m1.acquisition_source_profile WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)) AS source_hash,
  (SELECT md5(string_agg('CAMPAIGN|'||acquisition_campaign_id||'|'||row_hash,'||' ORDER BY acquisition_campaign_id)) FROM msbf_m1.acquisition_marketing_campaign WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)) AS campaign_hash,
  (SELECT md5(string_agg('FUNNEL|'||acquisition_campaign_id||'|'||stage_code||'|'||row_hash,'||' ORDER BY acquisition_campaign_id,stage_order)) FROM msbf_m1.acquisition_campaign_funnel_stage WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)) AS funnel_hash,
  (SELECT md5(string_agg('LEDGER|'||acquisition_cost_line_id||'|'||row_hash,'||' ORDER BY acquisition_cost_line_id)) FROM msbf_m1.acquisition_cost_ledger WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)) AS ledger_hash,
  (SELECT md5(string_agg('TOUCH|'||merchant_application_id||'|'||touchpoint_sequence||'|'||row_hash,'||' ORDER BY merchant_application_id,touchpoint_sequence)) FROM msbf_m1.application_acquisition_touchpoint WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)) AS touch_hash,
  (SELECT md5(string_agg('ATTRIBUTION|'||merchant_application_id||'|'||row_hash,'||' ORDER BY merchant_application_id)) FROM msbf_m1.application_acquisition_attribution_snapshot WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)) AS attribution_hash,
  (SELECT md5(string_agg('COST|'||merchant_application_id||'|'||row_hash,'||' ORDER BY merchant_application_id)) FROM msbf_m1.application_acquisition_cost_snapshot WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)) AS cost_hash,
  (SELECT md5(string_agg('COMPONENT|'||merchant_application_id||'|'||cost_component_code||'|'||row_hash,'||' ORDER BY merchant_application_id,cost_component_code)) FROM msbf_m1.application_acquisition_cost_component_value WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)) AS component_hash,
  (SELECT md5(string_agg('LATEST|'||merchant_application_id||'|'||contract_row_hash,'||' ORDER BY merchant_application_id)) FROM msbf_m1.application_acquisition_contract_latest WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)) AS latest_hash,
  (SELECT md5(string_agg('ARCHIVE|'||contract_version||'|'||merchant_application_id||'|'||contract_row_hash,'||' ORDER BY contract_version,merchant_application_id)) FROM msbf_m1.application_acquisition_contract_archive WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)) AS archive_hash
), hc AS(
 SELECT h.source_hash,h.campaign_hash,h.funnel_hash,h.ledger_hash,h.touch_hash,
        h.attribution_hash,h.cost_hash,h.component_hash,h.latest_hash,h.archive_hash,
  md5('M1_ACQUISITION_CONSUMPTION|1|'||(SELECT run_id FROM _m1_16_vctx)||'|M1_ACQUISITION_SCHEMA_V1|'||
      (SELECT source_m1_15_combined_hash FROM _m1_16_vctx)||'|'||(SELECT source_m1_14_combined_hash FROM _m1_16_vctx)||'|'||
      (SELECT policy_configuration_hash FROM _m1_16_vctx)||'|'||h.source_hash||'|'||h.campaign_hash||'|'||
      h.funnel_hash||'|'||h.ledger_hash||'|'||h.touch_hash||'|'||h.attribution_hash||'|'||h.cost_hash||'|'||
      h.component_hash||'|'||h.latest_hash||'|'||h.archive_hash) AS contract_hash
 FROM h
), entities AS(
 SELECT 'SOURCE|'||acquisition_source_code AS entity_key,row_hash FROM msbf_m1.acquisition_source_profile WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)
 UNION ALL SELECT 'CAMPAIGN|'||acquisition_campaign_id,row_hash FROM msbf_m1.acquisition_marketing_campaign WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)
 UNION ALL SELECT 'FUNNEL|'||acquisition_campaign_id||'|'||stage_code,row_hash FROM msbf_m1.acquisition_campaign_funnel_stage WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)
 UNION ALL SELECT 'LEDGER|'||acquisition_cost_line_id,row_hash FROM msbf_m1.acquisition_cost_ledger WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)
 UNION ALL SELECT 'TOUCH|'||merchant_application_id||'|'||touchpoint_sequence::text,row_hash FROM msbf_m1.application_acquisition_touchpoint WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)
 UNION ALL SELECT 'ATTRIBUTION|'||merchant_application_id,row_hash FROM msbf_m1.application_acquisition_attribution_snapshot WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)
 UNION ALL SELECT 'COST|'||merchant_application_id,row_hash FROM msbf_m1.application_acquisition_cost_snapshot WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)
 UNION ALL SELECT 'COMPONENT|'||merchant_application_id||'|'||cost_component_code,row_hash FROM msbf_m1.application_acquisition_cost_component_value WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)
 UNION ALL SELECT 'LATEST|'||merchant_application_id,contract_row_hash FROM msbf_m1.application_acquisition_contract_latest WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)
 UNION ALL SELECT 'ARCHIVE|'||contract_version::text||'|'||merchant_application_id,contract_row_hash FROM msbf_m1.application_acquisition_contract_archive WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)
 UNION ALL SELECT 'CONTRACT|'||contract_code||'|'||contract_version::text||'|'||module1_run_id::text,contract_row_hash FROM msbf_ctl.m1_16_acquisition_contract_registry WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)
)
SELECT hc.source_hash,hc.campaign_hash,hc.funnel_hash,hc.ledger_hash,hc.touch_hash,
       hc.attribution_hash,hc.cost_hash,hc.component_hash,hc.latest_hash,hc.archive_hash,hc.contract_hash,
       md5(string_agg(e.entity_key||'|'||e.row_hash,'||' ORDER BY e.entity_key)) AS combined_hash,
       count(*) AS canonical_entities
FROM hc CROSS JOIN entities e GROUP BY hc.source_hash,hc.campaign_hash,hc.funnel_hash,hc.ledger_hash,
 hc.touch_hash,hc.attribution_hash,hc.cost_hash,hc.component_hash,hc.latest_hash,hc.archive_hash,hc.contract_hash;

DROP TABLE IF EXISTS _m1_16_vrow_mismatches;
CREATE TEMP TABLE _m1_16_vrow_mismatches(
 entity_type text,entity_key text,stored_hash text,recomputed_hash text
) ON COMMIT DROP;
INSERT INTO _m1_16_vrow_mismatches
SELECT 'SOURCE',s.acquisition_source_code,s.row_hash,msbf_m1.m1_16_hash_jsonb(to_jsonb(s)-'row_hash'-'created_at')
FROM msbf_m1.acquisition_source_profile s WHERE s.module1_run_id=(SELECT run_id FROM _m1_16_vctx)
 AND s.row_hash IS DISTINCT FROM msbf_m1.m1_16_hash_jsonb(to_jsonb(s)-'row_hash'-'created_at')
UNION ALL
SELECT 'CAMPAIGN',c.acquisition_campaign_id,c.row_hash,msbf_m1.m1_16_hash_jsonb(to_jsonb(c)-'row_hash'-'created_at')
FROM msbf_m1.acquisition_marketing_campaign c WHERE c.module1_run_id=(SELECT run_id FROM _m1_16_vctx)
 AND c.row_hash IS DISTINCT FROM msbf_m1.m1_16_hash_jsonb(to_jsonb(c)-'row_hash'-'created_at')
UNION ALL
SELECT 'FUNNEL',f.acquisition_campaign_id||'|'||f.stage_code,f.row_hash,msbf_m1.m1_16_hash_jsonb(to_jsonb(f)-'row_hash'-'created_at')
FROM msbf_m1.acquisition_campaign_funnel_stage f WHERE f.module1_run_id=(SELECT run_id FROM _m1_16_vctx)
 AND f.row_hash IS DISTINCT FROM msbf_m1.m1_16_hash_jsonb(to_jsonb(f)-'row_hash'-'created_at')
UNION ALL
SELECT 'LEDGER',l.acquisition_cost_line_id,l.row_hash,msbf_m1.m1_16_hash_jsonb(to_jsonb(l)-'row_hash'-'created_at')
FROM msbf_m1.acquisition_cost_ledger l WHERE l.module1_run_id=(SELECT run_id FROM _m1_16_vctx)
 AND l.row_hash IS DISTINCT FROM msbf_m1.m1_16_hash_jsonb(to_jsonb(l)-'row_hash'-'created_at')
UNION ALL
SELECT 'TOUCHPOINT',t.merchant_application_id||'|'||t.touchpoint_sequence::text,t.row_hash,msbf_m1.m1_16_hash_jsonb(to_jsonb(t)-'row_hash'-'created_at')
FROM msbf_m1.application_acquisition_touchpoint t WHERE t.module1_run_id=(SELECT run_id FROM _m1_16_vctx)
 AND t.row_hash IS DISTINCT FROM msbf_m1.m1_16_hash_jsonb(to_jsonb(t)-'row_hash'-'created_at')
UNION ALL
SELECT 'ATTRIBUTION',a.merchant_application_id,a.row_hash,msbf_m1.m1_16_hash_jsonb(to_jsonb(a)-'row_hash'-'created_at')
FROM msbf_m1.application_acquisition_attribution_snapshot a WHERE a.module1_run_id=(SELECT run_id FROM _m1_16_vctx)
 AND a.row_hash IS DISTINCT FROM msbf_m1.m1_16_hash_jsonb(to_jsonb(a)-'row_hash'-'created_at')
UNION ALL
SELECT 'COST_SNAPSHOT',c.merchant_application_id,c.row_hash,msbf_m1.m1_16_hash_jsonb(to_jsonb(c)-'row_hash'-'created_at')
FROM msbf_m1.application_acquisition_cost_snapshot c WHERE c.module1_run_id=(SELECT run_id FROM _m1_16_vctx)
 AND c.row_hash IS DISTINCT FROM msbf_m1.m1_16_hash_jsonb(to_jsonb(c)-'row_hash'-'created_at')
UNION ALL
SELECT 'COMPONENT',v.merchant_application_id||'|'||v.cost_component_code,v.row_hash,msbf_m1.m1_16_hash_jsonb(to_jsonb(v)-'row_hash'-'created_at')
FROM msbf_m1.application_acquisition_cost_component_value v WHERE v.module1_run_id=(SELECT run_id FROM _m1_16_vctx)
 AND v.row_hash IS DISTINCT FROM msbf_m1.m1_16_hash_jsonb(to_jsonb(v)-'row_hash'-'created_at')
UNION ALL
SELECT 'LATEST',l.merchant_application_id,l.contract_row_hash,msbf_m1.m1_16_hash_jsonb(to_jsonb(l)-'contract_row_hash'-'created_at')
FROM msbf_m1.application_acquisition_contract_latest l WHERE l.module1_run_id=(SELECT run_id FROM _m1_16_vctx)
 AND l.contract_row_hash IS DISTINCT FROM msbf_m1.m1_16_hash_jsonb(to_jsonb(l)-'contract_row_hash'-'created_at')
UNION ALL
SELECT 'REGISTRY',c.contract_code||'|'||c.contract_version::text,c.contract_row_hash,
 msbf_m1.m1_16_hash_jsonb(to_jsonb(c)-'contract_row_hash'-'combined_set_hash'-'contract_status'-'generated_at'-'validated_at'-'accepted_at')
FROM msbf_ctl.m1_16_acquisition_contract_registry c WHERE c.module1_run_id=(SELECT run_id FROM _m1_16_vctx)
 AND c.contract_row_hash IS DISTINCT FROM msbf_m1.m1_16_hash_jsonb(to_jsonb(c)-'contract_row_hash'-'combined_set_hash'-'contract_status'-'generated_at'-'validated_at'-'accepted_at');

DROP TABLE IF EXISTS _m1_16_varchive_mismatches;
CREATE TEMP TABLE _m1_16_varchive_mismatches ON COMMIT DROP AS
SELECT coalesce(l.merchant_application_id,a.merchant_application_id) AS merchant_application_id,
       l.contract_row_hash AS latest_hash,a.contract_row_hash AS archive_hash,
       to_jsonb(l)-'created_at' AS expected_payload,a.contract_payload AS archive_payload
FROM msbf_m1.application_acquisition_contract_latest l
FULL JOIN msbf_m1.application_acquisition_contract_archive a
 ON a.module1_run_id=l.module1_run_id AND a.merchant_application_id=l.merchant_application_id
AND a.contract_code=l.contract_code AND a.contract_version=l.contract_version
WHERE coalesce(l.module1_run_id,a.module1_run_id)=(SELECT run_id FROM _m1_16_vctx)
  AND (l.contract_row_hash IS DISTINCT FROM a.contract_row_hash
    OR a.contract_payload IS DISTINCT FROM to_jsonb(l)-'created_at');

DROP TABLE IF EXISTS _m1_16_vfunnel;
CREATE TEMP TABLE _m1_16_vfunnel ON COMMIT DROP AS
SELECT f.module1_run_id,f.acquisition_campaign_id,f.stage_code,f.stage_order,
       f.period_start_date,f.period_end_date,f.stage_count,f.applicability_status,
       f.conversion_rate_from_prior,f.evidence_basis_code,f.evidence_status,f.row_hash,
       f.created_by_run_id,f.created_at,lag(f.stage_count) OVER(PARTITION BY f.acquisition_campaign_id ORDER BY f.stage_order) AS prior_count
FROM msbf_m1.acquisition_campaign_funnel_stage f WHERE f.module1_run_id=(SELECT run_id FROM _m1_16_vctx);

DROP TABLE IF EXISTS _m1_16_vallocation;
CREATE TEMP TABLE _m1_16_vallocation ON COMMIT DROP AS
WITH allocated AS(
 SELECT v.source_lineage_payload->>'primary_campaign_id' AS campaign_id,
        sum(coalesce(v.component_amount,0)) AS allocated_amount
 FROM msbf_m1.application_acquisition_cost_component_value v
 JOIN msbf_m1.acquisition_cost_ledger l
   ON l.module1_run_id=v.module1_run_id
  AND l.acquisition_campaign_id=v.source_lineage_payload->>'primary_campaign_id'
  AND NOT l.conditional_flag AND l.cost_component_code=v.cost_component_code
 WHERE v.module1_run_id=(SELECT run_id FROM _m1_16_vctx)
 GROUP BY v.source_lineage_payload->>'primary_campaign_id'
)
SELECT l.acquisition_campaign_id,l.gross_cost_amount,coalesce(a.allocated_amount,0)::numeric(18,2) AS allocated_amount,
       (coalesce(a.allocated_amount,0)-l.gross_cost_amount)::numeric(18,2) AS allocation_difference
FROM msbf_m1.acquisition_cost_ledger l
LEFT JOIN allocated a ON a.campaign_id=l.acquisition_campaign_id
WHERE l.module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND NOT l.conditional_flag;

DROP TABLE IF EXISTS _m1_16_vcomponent_rollup;
CREATE TEMP TABLE _m1_16_vcomponent_rollup ON COMMIT DROP AS
SELECT merchant_application_id,
 max(component_amount) FILTER(WHERE cost_component_code='PAID_MEDIA_COST') AS paid_media,
 max(component_amount) FILTER(WHERE cost_component_code='DIRECT_MAIL_EVENT_OUTBOUND_COST') AS direct_mail,
 max(component_amount) FILTER(WHERE cost_component_code='PURCHASED_LEAD_COST') AS purchased_lead,
 max(component_amount) FILTER(WHERE cost_component_code='INTERNAL_SALES_RM_COST') AS internal_rm,
 max(component_amount) FILTER(WHERE cost_component_code='AGENCY_CREATIVE_TECH_COST') AS agency_tech,
 max(component_amount) FILTER(WHERE cost_component_code='CAMPAIGN_OVERHEAD_COST') AS overhead,
 max(component_amount) FILTER(WHERE cost_component_code='ACQUISITION_INCENTIVE_COST') AS incentive,
 max(component_amount) FILTER(WHERE cost_component_code='DETAILED_CONDITIONAL_PARTNER_BROKER_COST') AS conditional_cost,
 max(component_amount) FILTER(WHERE cost_component_code='LEGACY_M1_14_ACQUISITION_COST') AS legacy,
 max(component_amount) FILTER(WHERE cost_component_code='IDENTIFIED_LEGACY_OVERLAP') AS overlap,
 max(component_amount) FILTER(WHERE cost_component_code='INCREMENTAL_ACQUISITION_COST_BEYOND_M1_14') AS incremental,
 max(component_amount) FILTER(WHERE cost_component_code='ENHANCED_TOTAL_ACQUISITION_COST_IF_BOOKED') AS enhanced,
 count(*) AS component_count
FROM msbf_m1.application_acquisition_cost_component_value
WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)
GROUP BY merchant_application_id;

DROP TABLE IF EXISTS _m1_16_vscenario;
CREATE TEMP TABLE _m1_16_vscenario ON COMMIT DROP AS
SELECT merchant_application_id,count(*) AS scenario_rows,
 count(DISTINCT scenario_id) AS scenario_count,
 count(DISTINCT coalesce(primary_source_code,'<NULL>')) AS source_variants,
 count(DISTINCT coalesce(primary_campaign_id,'<NULL>')) AS campaign_variants,
 count(DISTINCT coalesce(enhanced_total_acquisition_cost_if_booked::text,'<NULL>')) AS cost_variants
FROM msbf_m1.v_m1_16_module1_integrated_consumption
WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)
GROUP BY merchant_application_id;


DROP TABLE IF EXISTS _m1_16_validation;
CREATE TEMP TABLE _m1_16_validation(
 evidence_code text PRIMARY KEY,metric_name text NOT NULL,observed_value text NOT NULL,
 threshold_value text NOT NULL,status text NOT NULL,interpretation text NOT NULL
) ON COMMIT PRESERVE ROWS;
CREATE OR REPLACE FUNCTION pg_temp.m1_16_add_check(
 p_code text,p_name text,p_observed text,p_threshold text,p_pass boolean,p_interpretation text
) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
 INSERT INTO _m1_16_validation VALUES(
  p_code,p_name,coalesce(p_observed,'<NULL>'),coalesce(p_threshold,'<NULL>'),
  CASE WHEN coalesce(p_pass,false) THEN 'PASS' ELSE 'FAIL' END,p_interpretation
 );
END; $$;

DO $checks$
BEGIN
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_001_RUN_CODE','RUN_CODE',(SELECT run_code FROM _m1_16_vctx),'M1_V0_2_BASELINE_BUILD',(SELECT run_code='M1_V0_2_BASELINE_BUILD' FROM _m1_16_vctx),'Governed run code is preserved.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_002_RUN_VERSION','RUN_VERSION',(SELECT run_version::text FROM _m1_16_vctx),'1',(SELECT run_version=1 FROM _m1_16_vctx),'Governed run version is preserved.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_003_RUN_STATUS','RUN_STATUS',(SELECT run_status FROM _m1_16_vctx),'M1_16_GENERATED',(SELECT run_status='M1_16_GENERATED' FROM _m1_16_vctx),'Validation begins from committed generation.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_004_G1_PARAMETER_HASH','G1_PARAMETER_HASH',(SELECT parameter_snapshot_hash FROM _m1_16_vctx),'bd09e598c82db96e47459d77fd11e7c8',(SELECT parameter_snapshot_hash='bd09e598c82db96e47459d77fd11e7c8' FROM _m1_16_vctx),'Accepted G1 parameter snapshot is unchanged.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_005_G1_PROFILE_HASH','G1_PROFILE_HASH',(SELECT profile_snapshot_hash FROM _m1_16_vctx),'462cbd2ed92f68e5bdecf6b17537a973',(SELECT profile_snapshot_hash='462cbd2ed92f68e5bdecf6b17537a973' FROM _m1_16_vctx),'Accepted G1 profile snapshot is unchanged.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_006_G1_SOURCE_HASH','G1_SOURCE_HASH',(SELECT source_snapshot_hash FROM _m1_16_vctx),'93c3d1368fb2450ab4a08e2b721f92d3',(SELECT source_snapshot_hash='93c3d1368fb2450ab4a08e2b721f92d3' FROM _m1_16_vctx),'Accepted G1 source snapshot is unchanged.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_007_M1_14_COMBINED_HASH','M1_14_COMBINED_HASH',(SELECT source_m1_14_combined_hash FROM _m1_16_vctx),'3a47f59b56fa158c18c111caa1c64909',(SELECT source_m1_14_combined_hash='3a47f59b56fa158c18c111caa1c64909' FROM _m1_16_vctx),'Accepted M1.14 identity is preserved.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_008_M1_15_COMBINED_HASH','M1_15_COMBINED_HASH',(SELECT source_m1_15_combined_hash FROM _m1_16_vctx),'fcd2704e17ec0d2e73191ea36061d74b',(SELECT source_m1_15_combined_hash='fcd2704e17ec0d2e73191ea36061d74b' FROM _m1_16_vctx),'Accepted M1.15 identity is preserved.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_009_M1_15_LATEST_HASH','M1_15_LATEST_HASH',(SELECT latest_set_hash FROM msbf_ctl.m1_15_consumption_contract_registry WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND contract_code='M1_APPLICATION_CONSUMPTION' AND contract_version=1),'95b54308f082b0fc57be2dd370e94435',(SELECT latest_set_hash='95b54308f082b0fc57be2dd370e94435' FROM msbf_ctl.m1_15_consumption_contract_registry WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND contract_code='M1_APPLICATION_CONSUMPTION' AND contract_version=1),'Accepted M1.15 latest set is preserved.');
