      SELECT count(*) FILTER (WHERE evidence_code IN('M1_16_SOURCE_PROFILE_SET_HASH','M1_16_CAMPAIGN_SET_HASH','M1_16_FUNNEL_SET_HASH','M1_16_COST_LEDGER_SET_HASH','M1_16_TOUCHPOINT_SET_HASH','M1_16_ATTRIBUTION_SET_HASH','M1_16_COST_SNAPSHOT_SET_HASH','M1_16_COMPONENT_SET_HASH','M1_16_LATEST_SET_HASH','M1_16_ARCHIVE_SET_HASH','M1_16_CONTRACT_SET_HASH','M1_16_COMBINED_SET_HASH','M1_16_CANONICAL_ENTITY_COUNT','M1_16_CANONICAL_MISMATCH_COUNT','M1_16_SOURCE_PROFILE_ROW_COUNT','M1_16_CAMPAIGN_ROW_COUNT','M1_16_FUNNEL_ROW_COUNT','M1_16_COST_LEDGER_ROW_COUNT','M1_16_TOUCHPOINT_ROW_COUNT','M1_16_ATTRIBUTION_ROW_COUNT','M1_16_COST_SNAPSHOT_ROW_COUNT','M1_16_COMPONENT_ROW_COUNT','M1_16_LATEST_ROW_COUNT','M1_16_ARCHIVE_ROW_COUNT','M1_16_INTEGRATED_VIEW_ROW_COUNT'))=25
         AND count(DISTINCT evidence_code) FILTER (WHERE evidence_code IN('M1_16_SOURCE_PROFILE_SET_HASH','M1_16_CAMPAIGN_SET_HASH','M1_16_FUNNEL_SET_HASH','M1_16_COST_LEDGER_SET_HASH','M1_16_TOUCHPOINT_SET_HASH','M1_16_ATTRIBUTION_SET_HASH','M1_16_COST_SNAPSHOT_SET_HASH','M1_16_COMPONENT_SET_HASH','M1_16_LATEST_SET_HASH','M1_16_ARCHIVE_SET_HASH','M1_16_CONTRACT_SET_HASH','M1_16_COMBINED_SET_HASH','M1_16_CANONICAL_ENTITY_COUNT','M1_16_CANONICAL_MISMATCH_COUNT','M1_16_SOURCE_PROFILE_ROW_COUNT','M1_16_CAMPAIGN_ROW_COUNT','M1_16_FUNNEL_ROW_COUNT','M1_16_COST_LEDGER_ROW_COUNT','M1_16_TOUCHPOINT_ROW_COUNT','M1_16_ATTRIBUTION_ROW_COUNT','M1_16_COST_SNAPSHOT_ROW_COUNT','M1_16_COMPONENT_ROW_COUNT','M1_16_LATEST_ROW_COUNT','M1_16_ARCHIVE_ROW_COUNT','M1_16_INTEGRATED_VIEW_ROW_COUNT'))=25
      FROM msbf_ctl.run_evidence
      WHERE run_id=(SELECT run_id FROM _m1_16_vctx)
    ),
    'The exact 25-row governed generation-evidence inventory is complete; superseded audit-history evidence is retained separately and does not inflate the generation count.'
  );
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_051_SOURCE_GRAIN_UNIQUE','SOURCE_GRAIN_UNIQUE',(SELECT count(*)-count(DISTINCT acquisition_source_code) FROM msbf_m1.acquisition_source_profile WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx))::text,'0',(SELECT count(*)=count(DISTINCT acquisition_source_code) FROM msbf_m1.acquisition_source_profile WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)),'Source-profile code is unique.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_052_SOURCE_PARENT_COUNTS','SOURCE_PARENT_COUNTS',(SELECT string_agg(accepted_partner_channel_id||'='||n,',' ORDER BY accepted_partner_channel_id) FROM (SELECT accepted_partner_channel_id,count(*)::text n FROM msbf_m1.acquisition_source_profile WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) GROUP BY accepted_partner_channel_id) q),'CH_BANK_RELATIONSHIP=3,CH_BROKER_NETWORK=3,CH_DIGITAL_DIRECT=6,CH_PROCESSOR_DIRECT=3,CH_STRATEGIC_PARTNER=3',(SELECT count(*)=5 AND bool_and((accepted_partner_channel_id,n) IN (('CH_PROCESSOR_DIRECT',3),('CH_BANK_RELATIONSHIP',3),('CH_DIGITAL_DIRECT',6),('CH_STRATEGIC_PARTNER',3),('CH_BROKER_NETWORK',3))) FROM (SELECT accepted_partner_channel_id,count(*) n FROM msbf_m1.acquisition_source_profile WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) GROUP BY accepted_partner_channel_id) q),'Granular sources reconcile to the five accepted parent channels.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_053_SOURCE_APPROVAL','SOURCE_APPROVAL',(SELECT count(*)::text FROM msbf_m1.acquisition_source_profile WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND (NOT approved_source_flag OR governance_status<>'APPROVED' OR normalized_source_family<>source_classification)),'0',(SELECT count(*)=0 FROM msbf_m1.acquisition_source_profile WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND (NOT approved_source_flag OR governance_status<>'APPROVED' OR normalized_source_family<>source_classification)),'Only governed approved sources with aligned normalized taxonomy are used.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_054_SOURCE_EFFECTIVE_DATES','SOURCE_EFFECTIVE_DATES',(SELECT count(*)::text FROM msbf_m1.acquisition_source_profile WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND effective_end_date<=effective_start_date),'0',(SELECT count(*)=0 FROM msbf_m1.acquisition_source_profile WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND effective_end_date<=effective_start_date),'Source effective dates are valid.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_055_CAMPAIGN_GRAIN_UNIQUE','CAMPAIGN_GRAIN_UNIQUE',(SELECT count(*)-count(DISTINCT acquisition_campaign_id) FROM msbf_m1.acquisition_marketing_campaign WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx))::text,'0',(SELECT count(*)=count(DISTINCT acquisition_campaign_id) FROM msbf_m1.acquisition_marketing_campaign WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)),'Campaign code is unique.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_056_CAMPAIGN_SOURCE_CHANNEL_MAPPING','CAMPAIGN_SOURCE_CHANNEL_MAPPING',(SELECT count(*)::text FROM msbf_m1.acquisition_marketing_campaign c JOIN msbf_m1.acquisition_source_profile s ON s.module1_run_id=c.module1_run_id AND s.acquisition_source_code=c.acquisition_source_code WHERE c.module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND c.accepted_partner_channel_id<>s.accepted_partner_channel_id),'0',(SELECT count(*)=0 FROM msbf_m1.acquisition_marketing_campaign c JOIN msbf_m1.acquisition_source_profile s ON s.module1_run_id=c.module1_run_id AND s.acquisition_source_code=c.acquisition_source_code WHERE c.module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND c.accepted_partner_channel_id<>s.accepted_partner_channel_id),'Campaigns reconcile to approved sources and accepted parents.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_057_CAMPAIGN_APPROVAL','CAMPAIGN_APPROVAL',(SELECT count(*)::text FROM msbf_m1.acquisition_marketing_campaign WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND (campaign_status<>'ACTIVE' OR approval_status<>'APPROVED')),'0',(SELECT count(*)=0 FROM msbf_m1.acquisition_marketing_campaign WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND (campaign_status<>'ACTIVE' OR approval_status<>'APPROVED')),'Only active approved campaigns are used.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_058_CAMPAIGN_DATES','CAMPAIGN_DATES',(SELECT count(*)::text FROM msbf_m1.acquisition_marketing_campaign WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND effective_end_date<effective_start_date),'0',(SELECT count(*)=0 FROM msbf_m1.acquisition_marketing_campaign WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND effective_end_date<effective_start_date),'Campaign effective dates are valid.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_059_CAMPAIGN_SUBMITTED_TOTAL','CAMPAIGN_SUBMITTED_TOTAL',(SELECT sum(stage_count)::text FROM msbf_m1.acquisition_campaign_funnel_stage WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND stage_code='APPLICATION_SUBMITTED'),'750',(SELECT sum(stage_count)=750 FROM msbf_m1.acquisition_campaign_funnel_stage WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND stage_code='APPLICATION_SUBMITTED'),'Primary campaign submissions reconcile to the accepted 750 applications.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_060_FUNNEL_STAGES_PER_CAMPAIGN','FUNNEL_STAGES_PER_CAMPAIGN',(SELECT count(*)::text FROM (SELECT acquisition_campaign_id,count(*) n FROM msbf_m1.acquisition_campaign_funnel_stage WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) GROUP BY acquisition_campaign_id HAVING count(*)<>6) q),'0',(SELECT count(*)=0 FROM (SELECT acquisition_campaign_id,count(*) n FROM msbf_m1.acquisition_campaign_funnel_stage WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) GROUP BY acquisition_campaign_id HAVING count(*)<>6) q),'Every campaign has all six normalized funnel stages.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_061_FUNNEL_STAGE_ORDER','FUNNEL_STAGE_ORDER',(SELECT count(*)::text FROM msbf_m1.acquisition_campaign_funnel_stage f JOIN msbf_ref.acquisition_funnel_stage d ON d.stage_code=f.stage_code WHERE f.module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND f.stage_order<>d.stage_order),'0',(SELECT count(*)=0 FROM msbf_m1.acquisition_campaign_funnel_stage f JOIN msbf_ref.acquisition_funnel_stage d ON d.stage_code=f.stage_code WHERE f.module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND f.stage_order<>d.stage_order),'Persisted funnel stage order matches governance.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_062_FUNNEL_MONOTONICITY','FUNNEL_MONOTONICITY',(SELECT count(*)::text FROM _m1_16_vfunnel WHERE prior_count IS NOT NULL AND stage_count>prior_count),'0',(SELECT count(*)=0 FROM _m1_16_vfunnel WHERE prior_count IS NOT NULL AND stage_count>prior_count),'Funnel counts are nonincreasing.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_063_FUNNEL_CONVERSION_IDENTITY','FUNNEL_CONVERSION_IDENTITY',(SELECT count(*)::text FROM _m1_16_vfunnel WHERE prior_count IS NULL AND conversion_rate_from_prior IS NOT NULL OR prior_count IS NOT NULL AND conversion_rate_from_prior IS DISTINCT FROM round(stage_count::numeric/nullif(prior_count,0),8)),'0',(SELECT count(*)=0 FROM _m1_16_vfunnel WHERE (prior_count IS NULL AND conversion_rate_from_prior IS NOT NULL) OR (prior_count IS NOT NULL AND conversion_rate_from_prior IS DISTINCT FROM round(stage_count::numeric/nullif(prior_count,0),8))),'Funnel conversion rates derive from persisted counts.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_064_CAMPAIGN_ATTRIBUTION_SUBMISSION_RECONCILIATION','CAMPAIGN_ATTRIBUTION_SUBMISSION_RECONCILIATION',(SELECT count(*)::text FROM (SELECT f.acquisition_campaign_id,f.stage_count,count(a.merchant_application_id) n FROM msbf_m1.acquisition_campaign_funnel_stage f LEFT JOIN msbf_m1.application_acquisition_attribution_snapshot a ON a.module1_run_id=f.module1_run_id AND a.primary_campaign_id=f.acquisition_campaign_id WHERE f.module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND f.stage_code='APPLICATION_SUBMITTED' GROUP BY f.acquisition_campaign_id,f.stage_count HAVING f.stage_count<>count(a.merchant_application_id)) q),'0',(SELECT count(*)=0 FROM (SELECT f.acquisition_campaign_id,f.stage_count,count(a.merchant_application_id) n FROM msbf_m1.acquisition_campaign_funnel_stage f LEFT JOIN msbf_m1.application_acquisition_attribution_snapshot a ON a.module1_run_id=f.module1_run_id AND a.primary_campaign_id=f.acquisition_campaign_id WHERE f.module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND f.stage_code='APPLICATION_SUBMITTED' GROUP BY f.acquisition_campaign_id,f.stage_count HAVING f.stage_count<>count(a.merchant_application_id)) q),'Campaign submitted counts equal primary attributed applications.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_065_CAMPAIGN_SPEND_WITHIN_BUDGET','CAMPAIGN_SPEND_WITHIN_BUDGET',(SELECT count(*)::text FROM msbf_m1.acquisition_marketing_campaign WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND spend_amount>budget_amount),'0',(SELECT count(*)=0 FROM msbf_m1.acquisition_marketing_campaign WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND spend_amount>budget_amount),'Campaign spend does not exceed budget.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_066_LEDGER_GRAIN_UNIQUE','LEDGER_GRAIN_UNIQUE',(SELECT count(*)-count(DISTINCT acquisition_cost_line_id) FROM msbf_m1.acquisition_cost_ledger WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx))::text,'0',(SELECT count(*)=count(DISTINCT acquisition_cost_line_id) FROM msbf_m1.acquisition_cost_ledger WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)),'Cost-ledger line IDs are unique.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_067_LEDGER_LINES_PER_CAMPAIGN','LEDGER_LINES_PER_CAMPAIGN',(SELECT count(*)::text FROM (SELECT acquisition_campaign_id,count(*) n FROM msbf_m1.acquisition_cost_ledger WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) GROUP BY acquisition_campaign_id HAVING count(*)<>2) q),'0',(SELECT count(*)=0 FROM (SELECT acquisition_campaign_id,count(*) n FROM msbf_m1.acquisition_cost_ledger WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) GROUP BY acquisition_campaign_id HAVING count(*)<>2) q),'Each campaign has one incurred and one conditional ledger line.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_068_LEDGER_NONNEGATIVE','LEDGER_NONNEGATIVE',(SELECT count(*)::text FROM msbf_m1.acquisition_cost_ledger WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND (quantity<0 OR gross_cost_amount<0 OR coalesce(unit_cost_amount,0)<0 OR coalesce(unit_rate,0)<0)),'0',(SELECT count(*)=0 FROM msbf_m1.acquisition_cost_ledger WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND (quantity<0 OR gross_cost_amount<0 OR coalesce(unit_cost_amount,0)<0 OR coalesce(unit_rate,0)<0)),'Raw acquisition expense values are nonnegative.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_069_LEDGER_TYPED_VALUE','LEDGER_TYPED_VALUE',(SELECT count(*)::text FROM msbf_m1.acquisition_cost_ledger WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND num_nonnulls(unit_cost_amount,unit_rate)<>1),'0',(SELECT count(*)=0 FROM msbf_m1.acquisition_cost_ledger WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND num_nonnulls(unit_cost_amount,unit_rate)<>1),'Every ledger line has exactly one unit-cost or rate value.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_070_LEDGER_SOURCE_PERMISSION','LEDGER_SOURCE_PERMISSION',(SELECT count(*)::text FROM msbf_m1.acquisition_cost_ledger l JOIN msbf_m1.acquisition_source_profile s ON s.module1_run_id=l.module1_run_id AND s.acquisition_source_code=l.acquisition_source_code WHERE l.module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND (NOT (l.cost_basis_code=ANY(s.permitted_cost_basis_codes)) OR NOT (l.cost_timing_code=ANY(s.permitted_cost_timing_codes)))),'0',(SELECT count(*)=0 FROM msbf_m1.acquisition_cost_ledger l JOIN msbf_m1.acquisition_source_profile s ON s.module1_run_id=l.module1_run_id AND s.acquisition_source_code=l.acquisition_source_code WHERE l.module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND (NOT (l.cost_basis_code=ANY(s.permitted_cost_basis_codes)) OR NOT (l.cost_timing_code=ANY(s.permitted_cost_timing_codes)))),'Cost basis and timing are permitted for the governed source.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_071_LEDGER_TIMING_SEPARATION','LEDGER_TIMING_SEPARATION',(SELECT count(*)::text FROM msbf_m1.acquisition_cost_ledger WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND ((conditional_flag AND cost_timing_code NOT LIKE 'CONDITIONAL_%') OR (NOT conditional_flag AND cost_timing_code LIKE 'CONDITIONAL_%'))),'0',(SELECT count(*)=0 FROM msbf_m1.acquisition_cost_ledger WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND ((conditional_flag AND cost_timing_code NOT LIKE 'CONDITIONAL_%') OR (NOT conditional_flag AND cost_timing_code LIKE 'CONDITIONAL_%'))) ,'Already-incurred and conditional acquisition costs remain separate.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_072_CAMPAIGN_ALLOCATION_RECONCILIATION','CAMPAIGN_ALLOCATION_RECONCILIATION',(SELECT count(*)::text FROM _m1_16_vallocation WHERE allocation_difference<>0),'0',(SELECT count(*)=0 FROM _m1_16_vallocation WHERE allocation_difference<>0),'Application allocations reconcile exactly to campaign spend at cent scale.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_073_TOUCHPOINT_GRAIN_UNIQUE','TOUCHPOINT_GRAIN_UNIQUE',(SELECT count(*)-count(DISTINCT merchant_application_id||'|'||touchpoint_sequence) FROM msbf_m1.application_acquisition_touchpoint WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx))::text,'0',(SELECT count(*)=count(DISTINCT merchant_application_id||'|'||touchpoint_sequence) FROM msbf_m1.application_acquisition_touchpoint WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)),'Application/touchpoint sequence grain is unique.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_074_TOUCHPOINT_COUNT_BOUND','TOUCHPOINT_COUNT_BOUND',(SELECT count(*)::text FROM (SELECT merchant_application_id,count(*) n FROM msbf_m1.application_acquisition_touchpoint WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) GROUP BY merchant_application_id HAVING count(*) NOT BETWEEN 1 AND 3) q),'0',(SELECT count(*)=0 FROM (SELECT merchant_application_id,count(*) n FROM msbf_m1.application_acquisition_touchpoint WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) GROUP BY merchant_application_id HAVING count(*) NOT BETWEEN 1 AND 3) q),'Touchpoint population is bounded to one through three per application.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_075_ATTRIBUTION_WEIGHT_SUM','ATTRIBUTION_WEIGHT_SUM',(SELECT count(*)::text FROM (SELECT merchant_application_id,sum(attribution_weight) w FROM msbf_m1.application_acquisition_touchpoint WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) GROUP BY merchant_application_id HAVING sum(attribution_weight)<>1.000000) q),'0',(SELECT count(*)=0 FROM (SELECT merchant_application_id,sum(attribution_weight) w FROM msbf_m1.application_acquisition_touchpoint WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) GROUP BY merchant_application_id HAVING sum(attribution_weight)<>1.000000) q),'Primary and assisted weights sum exactly to one.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_076_ONE_FIRST_TOUCH','ONE_FIRST_TOUCH',(SELECT count(*)::text FROM (SELECT merchant_application_id,count(*) FILTER(WHERE first_touch_flag) n FROM msbf_m1.application_acquisition_touchpoint WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) GROUP BY merchant_application_id HAVING count(*) FILTER(WHERE first_touch_flag)<>1) q),'0',(SELECT count(*)=0 FROM (SELECT merchant_application_id,count(*) FILTER(WHERE first_touch_flag) n FROM msbf_m1.application_acquisition_touchpoint WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) GROUP BY merchant_application_id HAVING count(*) FILTER(WHERE first_touch_flag)<>1) q),'Exactly one governed touchpoint role per application.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_077_ONE_LAST_TOUCH','ONE_LAST_TOUCH',(SELECT count(*)::text FROM (SELECT merchant_application_id,count(*) FILTER(WHERE last_touch_flag) n FROM msbf_m1.application_acquisition_touchpoint WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) GROUP BY merchant_application_id HAVING count(*) FILTER(WHERE last_touch_flag)<>1) q),'0',(SELECT count(*)=0 FROM (SELECT merchant_application_id,count(*) FILTER(WHERE last_touch_flag) n FROM msbf_m1.application_acquisition_touchpoint WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) GROUP BY merchant_application_id HAVING count(*) FILTER(WHERE last_touch_flag)<>1) q),'Exactly one governed touchpoint role per application.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_078_ONE_PRIMARY_TOUCH','ONE_PRIMARY_TOUCH',(SELECT count(*)::text FROM (SELECT merchant_application_id,count(*) FILTER(WHERE primary_attribution_flag) n FROM msbf_m1.application_acquisition_touchpoint WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) GROUP BY merchant_application_id HAVING count(*) FILTER(WHERE primary_attribution_flag)<>1) q),'0',(SELECT count(*)=0 FROM (SELECT merchant_application_id,count(*) FILTER(WHERE primary_attribution_flag) n FROM msbf_m1.application_acquisition_touchpoint WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) GROUP BY merchant_application_id HAVING count(*) FILTER(WHERE primary_attribution_flag)<>1) q),'Exactly one governed touchpoint role per application.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_079_TOUCHPOINT_TEMPORAL_BOUNDARY','TOUCHPOINT_TEMPORAL_BOUNDARY',(SELECT count(*)::text FROM msbf_m1.application_acquisition_touchpoint t JOIN msbf_m1.merchant_application a ON a.merchant_application_id=t.merchant_application_id WHERE t.module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND t.touchpoint_timestamp>a.application_date::timestamp+interval '23 hours 59 minutes 59 seconds'),'0',(SELECT count(*)=0 FROM msbf_m1.application_acquisition_touchpoint t JOIN msbf_m1.merchant_application a ON a.merchant_application_id=t.merchant_application_id WHERE t.module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND t.touchpoint_timestamp>a.application_date::timestamp+interval '23 hours 59 minutes 59 seconds'),'No touchpoint occurs after application submission.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_080_TOUCHPOINT_SOURCE_CAMPAIGN_ACTIVE','TOUCHPOINT_SOURCE_CAMPAIGN_ACTIVE',(SELECT count(*)::text FROM msbf_m1.application_acquisition_touchpoint t JOIN msbf_m1.acquisition_source_profile s ON s.module1_run_id=t.module1_run_id AND s.acquisition_source_code=t.acquisition_source_code JOIN msbf_m1.acquisition_marketing_campaign c ON c.module1_run_id=t.module1_run_id AND c.acquisition_campaign_id=t.acquisition_campaign_id WHERE t.module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND (NOT s.approved_source_flag OR c.approval_status<>'APPROVED' OR c.campaign_status<>'ACTIVE' OR t.touchpoint_timestamp::date NOT BETWEEN c.effective_start_date AND c.effective_end_date)),'0',(SELECT count(*)=0 FROM msbf_m1.application_acquisition_touchpoint t JOIN msbf_m1.acquisition_source_profile s ON s.module1_run_id=t.module1_run_id AND s.acquisition_source_code=t.acquisition_source_code JOIN msbf_m1.acquisition_marketing_campaign c ON c.module1_run_id=t.module1_run_id AND c.acquisition_campaign_id=t.acquisition_campaign_id WHERE t.module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND (NOT s.approved_source_flag OR c.approval_status<>'APPROVED' OR c.campaign_status<>'ACTIVE' OR t.touchpoint_timestamp::date NOT BETWEEN c.effective_start_date AND c.effective_end_date)),'Every touchpoint uses an approved active source and campaign.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_081_TOUCHPOINT_PARENT_ALIGNMENT','TOUCHPOINT_PARENT_ALIGNMENT',(SELECT count(*)::text FROM msbf_m1.application_acquisition_touchpoint t JOIN msbf_m1.acquisition_source_profile s ON s.module1_run_id=t.module1_run_id AND s.acquisition_source_code=t.acquisition_source_code WHERE t.module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND t.accepted_partner_channel_id<>s.accepted_partner_channel_id),'0',(SELECT count(*)=0 FROM msbf_m1.application_acquisition_touchpoint t JOIN msbf_m1.acquisition_source_profile s ON s.module1_run_id=t.module1_run_id AND s.acquisition_source_code=t.acquisition_source_code WHERE t.module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND t.accepted_partner_channel_id<>s.accepted_partner_channel_id),'Touchpoints retain accepted parent-channel lineage.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_082_ATTRIBUTION_ONE_PER_APPLICATION','ATTRIBUTION_ONE_PER_APPLICATION',(SELECT count(*)-count(DISTINCT merchant_application_id) FROM msbf_m1.application_acquisition_attribution_snapshot WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx))::text,'0',(SELECT count(*)=count(DISTINCT merchant_application_id) FROM msbf_m1.application_acquisition_attribution_snapshot WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)),'Exactly one attribution snapshot exists per application.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_083_PRIMARY_ATTRIBUTION_MAPPING','PRIMARY_ATTRIBUTION_MAPPING',(SELECT count(*)::text FROM msbf_m1.application_acquisition_attribution_snapshot a JOIN msbf_m1.application_acquisition_touchpoint t ON t.module1_run_id=a.module1_run_id AND t.merchant_application_id=a.merchant_application_id AND t.primary_attribution_flag WHERE a.module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND (a.primary_source_code<>t.acquisition_source_code OR a.primary_campaign_id<>t.acquisition_campaign_id)),'0',(SELECT count(*)=0 FROM msbf_m1.application_acquisition_attribution_snapshot a JOIN msbf_m1.application_acquisition_touchpoint t ON t.module1_run_id=a.module1_run_id AND t.merchant_application_id=a.merchant_application_id AND t.primary_attribution_flag WHERE a.module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND (a.primary_source_code<>t.acquisition_source_code OR a.primary_campaign_id<>t.acquisition_campaign_id)),'Primary attribution reproduces the primary touch.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_084_FIRST_TOUCH_MAPPING','FIRST_TOUCH_MAPPING',(SELECT count(*)::text FROM msbf_m1.application_acquisition_attribution_snapshot a JOIN msbf_m1.application_acquisition_touchpoint t ON t.module1_run_id=a.module1_run_id AND t.merchant_application_id=a.merchant_application_id AND t.first_touch_flag WHERE a.module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND (a.first_touch_source_code<>t.acquisition_source_code OR a.first_touch_campaign_id<>t.acquisition_campaign_id)),'0',(SELECT count(*)=0 FROM msbf_m1.application_acquisition_attribution_snapshot a JOIN msbf_m1.application_acquisition_touchpoint t ON t.module1_run_id=a.module1_run_id AND t.merchant_application_id=a.merchant_application_id AND t.first_touch_flag WHERE a.module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND (a.first_touch_source_code<>t.acquisition_source_code OR a.first_touch_campaign_id<>t.acquisition_campaign_id)),'First-touch attribution is exact.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_085_LAST_TOUCH_MAPPING','LAST_TOUCH_MAPPING',(SELECT count(*)::text FROM msbf_m1.application_acquisition_attribution_snapshot a JOIN msbf_m1.application_acquisition_touchpoint t ON t.module1_run_id=a.module1_run_id AND t.merchant_application_id=a.merchant_application_id AND t.last_touch_flag WHERE a.module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND (a.last_touch_source_code<>t.acquisition_source_code OR a.last_touch_campaign_id<>t.acquisition_campaign_id)),'0',(SELECT count(*)=0 FROM msbf_m1.application_acquisition_attribution_snapshot a JOIN msbf_m1.application_acquisition_touchpoint t ON t.module1_run_id=a.module1_run_id AND t.merchant_application_id=a.merchant_application_id AND t.last_touch_flag WHERE a.module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND (a.last_touch_source_code<>t.acquisition_source_code OR a.last_touch_campaign_id<>t.acquisition_campaign_id)),'Last-touch attribution is exact.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_086_ATTRIBUTION_TOUCH_COUNTS','ATTRIBUTION_TOUCH_COUNTS',(SELECT count(*)::text FROM msbf_m1.application_acquisition_attribution_snapshot a WHERE a.module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND (a.touchpoint_count<>(SELECT count(*) FROM msbf_m1.application_acquisition_touchpoint t WHERE t.module1_run_id=a.module1_run_id AND t.merchant_application_id=a.merchant_application_id) OR a.assisted_touch_count<>a.touchpoint_count-1)),'0',(SELECT count(*)=0 FROM msbf_m1.application_acquisition_attribution_snapshot a WHERE a.module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND (a.touchpoint_count<>(SELECT count(*) FROM msbf_m1.application_acquisition_touchpoint t WHERE t.module1_run_id=a.module1_run_id AND t.merchant_application_id=a.merchant_application_id) OR a.assisted_touch_count<>a.touchpoint_count-1)),'Attribution snapshot touch counts reconcile.');
  PERFORM pg_temp.m1_16_add_check(
    'M1_16_POS_087_ATTRIBUTION_PARENT_RECONCILIATION',
    'ATTRIBUTION_PARENT_RECONCILIATION',
    (
      SELECT concat_ws('|',
        'parent_mismatches='||count(*) FILTER (
          WHERE a.accepted_partner_channel_id IS DISTINCT FROM s.accepted_partner_channel_id
        ),
        'status_mismatches='||count(*) FILTER (
          WHERE a.parent_channel_reconciliation_status IS DISTINCT FROM
                CASE WHEN a.attribution_evidence_status='BLOCKED'
                     THEN 'BLOCKED_CONFLICT' ELSE 'MATCH' END
        ),
        'blocked_conflicts_diagnostic='||count(*) FILTER (
          WHERE a.attribution_evidence_status='BLOCKED'
            AND a.parent_channel_reconciliation_status='BLOCKED_CONFLICT'
        )
      )
      FROM msbf_m1.application_acquisition_attribution_snapshot a
      JOIN msbf_m1.acquisition_source_profile s
        ON s.module1_run_id=a.module1_run_id
       AND s.acquisition_source_code=a.primary_source_code
      WHERE a.module1_run_id=(SELECT run_id FROM _m1_16_vctx)
    ),
    'parent_mismatches=0|status_mismatches=0',
    (
      SELECT count(*) FILTER (
               WHERE a.accepted_partner_channel_id IS DISTINCT FROM s.accepted_partner_channel_id
             )=0
         AND count(*) FILTER (
               WHERE a.parent_channel_reconciliation_status IS DISTINCT FROM
                     CASE WHEN a.attribution_evidence_status='BLOCKED'
                          THEN 'BLOCKED_CONFLICT' ELSE 'MATCH' END
             )=0
      FROM msbf_m1.application_acquisition_attribution_snapshot a
      JOIN msbf_m1.acquisition_source_profile s
        ON s.module1_run_id=a.module1_run_id
       AND s.acquisition_source_code=a.primary_source_code
      WHERE a.module1_run_id=(SELECT run_id FROM _m1_16_vctx)
    ),
    'Primary sources retain accepted parent-channel lineage; BLOCKED_CONFLICT is the governed status for evidence-blocked attribution and remains visible as a diagnostic.'
  );
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_088_ATTRIBUTION_EVIDENCE_FALLBACK','ATTRIBUTION_EVIDENCE_FALLBACK',(SELECT count(*)::text FROM msbf_m1.application_acquisition_attribution_snapshot WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND ((attribution_evidence_status='BLOCKED' AND fallback_path_code<>'PARENT_CHANNEL_FALLBACK') OR (attribution_evidence_status='COMPLETE' AND fallback_path_code<>'NONE') OR (attribution_evidence_status='PARTIAL' AND fallback_path_code<>'GOVERNED_PRIMARY_TOUCH'))),'0',(SELECT count(*)=0 FROM msbf_m1.application_acquisition_attribution_snapshot WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND ((attribution_evidence_status='BLOCKED' AND fallback_path_code<>'PARENT_CHANNEL_FALLBACK') OR (attribution_evidence_status='COMPLETE' AND fallback_path_code<>'NONE') OR (attribution_evidence_status='PARTIAL' AND fallback_path_code<>'GOVERNED_PRIMARY_TOUCH'))),'Attribution evidence and fallback routes reconcile.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_089_ATTRIBUTION_CONFIDENCE_TIER','ATTRIBUTION_CONFIDENCE_TIER',(SELECT count(*)::text FROM msbf_m1.application_acquisition_attribution_snapshot WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND attribution_confidence_tier IS DISTINCT FROM CASE WHEN attribution_confidence_score>=0.90 THEN 'HIGH' WHEN attribution_confidence_score>=0.70 THEN 'MEDIUM' WHEN attribution_confidence_score>=0.50 THEN 'LOW' ELSE 'INSUFFICIENT' END),'0',(SELECT count(*)=0 FROM msbf_m1.application_acquisition_attribution_snapshot WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND attribution_confidence_tier IS DISTINCT FROM CASE WHEN attribution_confidence_score>=0.90 THEN 'HIGH' WHEN attribution_confidence_score>=0.70 THEN 'MEDIUM' WHEN attribution_confidence_score>=0.50 THEN 'LOW' ELSE 'INSUFFICIENT' END),'Attribution confidence tier maps to the persisted score.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_090_ATTRIBUTION_ROW_HASH','ATTRIBUTION_ROW_HASH',(SELECT count(*)::text FROM _m1_16_vrow_mismatches WHERE entity_type='ATTRIBUTION'),'0',(SELECT count(*)=0 FROM _m1_16_vrow_mismatches WHERE entity_type='ATTRIBUTION'),'Attribution row hashes reconstruct from physical fields.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_091_COST_ONE_PER_APPLICATION','COST_ONE_PER_APPLICATION',(SELECT count(*)-count(DISTINCT merchant_application_id) FROM msbf_m1.application_acquisition_cost_snapshot WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx))::text,'0',(SELECT count(*)=count(DISTINCT merchant_application_id) FROM msbf_m1.application_acquisition_cost_snapshot WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)),'Exactly one cost snapshot exists per application.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_092_DIRECT_ATTRIBUTABLE_IDENTITY','DIRECT_ATTRIBUTABLE_IDENTITY',(SELECT count(*)::text FROM msbf_m1.application_acquisition_cost_snapshot WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND direct_attributable_incurred_cost_amount IS DISTINCT FROM paid_media_cost_amount+direct_mail_event_outbound_cost_amount+purchased_lead_cost_amount+acquisition_incentive_cost_amount),'0',(SELECT count(*)=0 FROM msbf_m1.application_acquisition_cost_snapshot WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND direct_attributable_incurred_cost_amount IS DISTINCT FROM paid_media_cost_amount+direct_mail_event_outbound_cost_amount+purchased_lead_cost_amount+acquisition_incentive_cost_amount),'Direct-attributable incurred cost identity reconciles.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_093_INTERNAL_ALLOCATION_IDENTITY','INTERNAL_ALLOCATION_IDENTITY',(SELECT count(*)::text FROM msbf_m1.application_acquisition_cost_snapshot WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND internally_allocated_acquisition_cost_amount IS DISTINCT FROM internal_sales_rm_cost_amount+agency_creative_tech_cost_amount+campaign_overhead_cost_amount),'0',(SELECT count(*)=0 FROM msbf_m1.application_acquisition_cost_snapshot WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND internally_allocated_acquisition_cost_amount IS DISTINCT FROM internal_sales_rm_cost_amount+agency_creative_tech_cost_amount+campaign_overhead_cost_amount),'Internally allocated acquisition-cost identity reconciles.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_094_TOTAL_INCURRED_IDENTITY','TOTAL_INCURRED_IDENTITY',(SELECT count(*)::text FROM msbf_m1.application_acquisition_cost_snapshot WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND total_incurred_pre_application_cost_amount IS DISTINCT FROM direct_attributable_incurred_cost_amount+internally_allocated_acquisition_cost_amount),'0',(SELECT count(*)=0 FROM msbf_m1.application_acquisition_cost_snapshot WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND total_incurred_pre_application_cost_amount IS DISTINCT FROM direct_attributable_incurred_cost_amount+internally_allocated_acquisition_cost_amount),'Detailed incurred acquisition cost reconciles.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_095_DETAILED_TOTAL_IF_BOOKED_IDENTITY','DETAILED_TOTAL_IF_BOOKED_IDENTITY',(SELECT count(*)::text FROM msbf_m1.application_acquisition_cost_snapshot WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND detailed_total_acquisition_cost_if_booked IS DISTINCT FROM total_incurred_pre_application_cost_amount+detailed_conditional_partner_broker_cost_amount),'0',(SELECT count(*)=0 FROM msbf_m1.application_acquisition_cost_snapshot WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND detailed_total_acquisition_cost_if_booked IS DISTINCT FROM total_incurred_pre_application_cost_amount+detailed_conditional_partner_broker_cost_amount),'Detailed total acquisition cost if booked reconciles.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_096_M1_14_LEGACY_INHERITANCE','M1_14_LEGACY_INHERITANCE',(SELECT count(*)::text FROM msbf_m1.application_acquisition_cost_snapshot c JOIN msbf_m1.application_unit_economics_snapshot e ON e.module1_run_id=c.module1_run_id AND e.merchant_application_id=c.merchant_application_id JOIN msbf_ctl.scenario_registry sr ON sr.scenario_id=e.scenario_id AND sr.scenario_code='BASELINE' WHERE c.module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND (c.accepted_m1_14_acquisition_cost_rate IS DISTINCT FROM e.partner_acquisition_cost_rate OR c.accepted_m1_14_acquisition_cost_amount IS DISTINCT FROM e.partner_acquisition_cost_amount OR c.m1_14_baseline_row_hash<>e.row_hash)),'0',(SELECT count(*)=0 FROM msbf_m1.application_acquisition_cost_snapshot c JOIN msbf_m1.application_unit_economics_snapshot e ON e.module1_run_id=c.module1_run_id AND e.merchant_application_id=c.merchant_application_id JOIN msbf_ctl.scenario_registry sr ON sr.scenario_id=e.scenario_id AND sr.scenario_code='BASELINE' WHERE c.module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND (c.accepted_m1_14_acquisition_cost_rate IS DISTINCT FROM e.partner_acquisition_cost_rate OR c.accepted_m1_14_acquisition_cost_amount IS DISTINCT FROM e.partner_acquisition_cost_amount OR c.m1_14_baseline_row_hash<>e.row_hash)),'Accepted M1.14 acquisition rate, amount, and lineage are inherited exactly once per application.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_097_OVERLAP_BOUNDS','OVERLAP_BOUNDS',(SELECT count(*)::text FROM msbf_m1.application_acquisition_cost_snapshot WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND identified_legacy_overlap_amount IS NOT NULL AND (identified_legacy_overlap_amount<0 OR identified_legacy_overlap_amount>accepted_m1_14_acquisition_cost_amount OR identified_legacy_overlap_amount>mapped_detailed_cost_potentially_represented)),'0',(SELECT count(*)=0 FROM msbf_m1.application_acquisition_cost_snapshot WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND identified_legacy_overlap_amount IS NOT NULL AND (identified_legacy_overlap_amount<0 OR identified_legacy_overlap_amount>accepted_m1_14_acquisition_cost_amount OR identified_legacy_overlap_amount>mapped_detailed_cost_potentially_represented)),'Identified overlap is nonnegative and bounded by both legacy and mapped detailed cost.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_098_UNMAPPED_LEGACY_IDENTITY','UNMAPPED_LEGACY_IDENTITY',(SELECT count(*)::text FROM msbf_m1.application_acquisition_cost_snapshot WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND acquisition_contract_evidence_status<>'BLOCKED' AND unmapped_legacy_proxy_amount IS DISTINCT FROM accepted_m1_14_acquisition_cost_amount-identified_legacy_overlap_amount),'0',(SELECT count(*)=0 FROM msbf_m1.application_acquisition_cost_snapshot WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND acquisition_contract_evidence_status<>'BLOCKED' AND unmapped_legacy_proxy_amount IS DISTINCT FROM accepted_m1_14_acquisition_cost_amount-identified_legacy_overlap_amount),'Unmapped legacy proxy identity reconciles.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_099_INCREMENTAL_COST_IDENTITY','INCREMENTAL_COST_IDENTITY',(SELECT count(*)::text FROM msbf_m1.application_acquisition_cost_snapshot WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND acquisition_contract_evidence_status<>'BLOCKED' AND incremental_acquisition_cost_beyond_m1_14 IS DISTINCT FROM detailed_total_acquisition_cost_if_booked-identified_legacy_overlap_amount),'0',(SELECT count(*)=0 FROM msbf_m1.application_acquisition_cost_snapshot WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND acquisition_contract_evidence_status<>'BLOCKED' AND incremental_acquisition_cost_beyond_m1_14 IS DISTINCT FROM detailed_total_acquisition_cost_if_booked-identified_legacy_overlap_amount),'Incremental M1.16 cost beyond M1.14 reconciles.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_100_ENHANCED_TOTAL_IDENTITY','ENHANCED_TOTAL_IDENTITY',(SELECT count(*)::text FROM msbf_m1.application_acquisition_cost_snapshot WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND acquisition_contract_evidence_status<>'BLOCKED' AND enhanced_total_acquisition_cost_if_booked IS DISTINCT FROM accepted_m1_14_acquisition_cost_amount+incremental_acquisition_cost_beyond_m1_14),'0',(SELECT count(*)=0 FROM msbf_m1.application_acquisition_cost_snapshot WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND acquisition_contract_evidence_status<>'BLOCKED' AND enhanced_total_acquisition_cost_if_booked IS DISTINCT FROM accepted_m1_14_acquisition_cost_amount+incremental_acquisition_cost_beyond_m1_14),'Enhanced fully loaded acquisition cost reconciles without double counting.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_101_BLOCKED_COST_GATING','BLOCKED_COST_GATING',(SELECT count(*)::text FROM msbf_m1.application_acquisition_cost_snapshot WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND acquisition_contract_evidence_status='BLOCKED' AND num_nonnulls(identified_legacy_overlap_amount,unmapped_legacy_proxy_amount,incremental_acquisition_cost_beyond_m1_14,enhanced_total_acquisition_cost_if_booked)<>0),'0',(SELECT count(*)=0 FROM msbf_m1.application_acquisition_cost_snapshot WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND acquisition_contract_evidence_status='BLOCKED' AND num_nonnulls(identified_legacy_overlap_amount,unmapped_legacy_proxy_amount,incremental_acquisition_cost_beyond_m1_14,enhanced_total_acquisition_cost_if_booked)<>0),'Blocked overlap and fully loaded totals remain null; known components remain visible.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_102_COMPONENTS_PER_APPLICATION','COMPONENTS_PER_APPLICATION',(SELECT count(*)::text FROM _m1_16_vcomponent_rollup WHERE component_count<>12),'0',(SELECT count(*)=0 FROM _m1_16_vcomponent_rollup WHERE component_count<>12),'Every application has the fixed 12-component acquisition dictionary.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_103_WIDE_LONG_COMPONENT_RECONCILIATION','WIDE_LONG_COMPONENT_RECONCILIATION',(SELECT count(*)::text FROM msbf_m1.application_acquisition_cost_snapshot c JOIN _m1_16_vcomponent_rollup v ON v.merchant_application_id=c.merchant_application_id WHERE c.module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND (c.paid_media_cost_amount IS DISTINCT FROM coalesce(v.paid_media,0) OR c.direct_mail_event_outbound_cost_amount IS DISTINCT FROM coalesce(v.direct_mail,0) OR c.purchased_lead_cost_amount IS DISTINCT FROM coalesce(v.purchased_lead,0) OR c.internal_sales_rm_cost_amount IS DISTINCT FROM coalesce(v.internal_rm,0) OR c.agency_creative_tech_cost_amount IS DISTINCT FROM coalesce(v.agency_tech,0) OR c.campaign_overhead_cost_amount IS DISTINCT FROM coalesce(v.overhead,0) OR c.acquisition_incentive_cost_amount IS DISTINCT FROM coalesce(v.incentive,0) OR c.detailed_conditional_partner_broker_cost_amount IS DISTINCT FROM v.conditional_cost OR c.accepted_m1_14_acquisition_cost_amount IS DISTINCT FROM v.legacy OR c.identified_legacy_overlap_amount IS DISTINCT FROM v.overlap OR c.incremental_acquisition_cost_beyond_m1_14 IS DISTINCT FROM v.incremental OR c.enhanced_total_acquisition_cost_if_booked IS DISTINCT FROM v.enhanced)),'0',(SELECT count(*)=0 FROM msbf_m1.application_acquisition_cost_snapshot c JOIN _m1_16_vcomponent_rollup v ON v.merchant_application_id=c.merchant_application_id WHERE c.module1_run_id=(SELECT run_id FROM _m1_16_vctx) AND (c.paid_media_cost_amount IS DISTINCT FROM coalesce(v.paid_media,0) OR c.direct_mail_event_outbound_cost_amount IS DISTINCT FROM coalesce(v.direct_mail,0) OR c.purchased_lead_cost_amount IS DISTINCT FROM coalesce(v.purchased_lead,0) OR c.internal_sales_rm_cost_amount IS DISTINCT FROM coalesce(v.internal_rm,0) OR c.agency_creative_tech_cost_amount IS DISTINCT FROM coalesce(v.agency_tech,0) OR c.campaign_overhead_cost_amount IS DISTINCT FROM coalesce(v.overhead,0) OR c.acquisition_incentive_cost_amount IS DISTINCT FROM coalesce(v.incentive,0) OR c.detailed_conditional_partner_broker_cost_amount IS DISTINCT FROM v.conditional_cost OR c.accepted_m1_14_acquisition_cost_amount IS DISTINCT FROM v.legacy OR c.identified_legacy_overlap_amount IS DISTINCT FROM v.overlap OR c.incremental_acquisition_cost_beyond_m1_14 IS DISTINCT FROM v.incremental OR c.enhanced_total_acquisition_cost_if_booked IS DISTINCT FROM v.enhanced)),'Wide acquisition snapshot fields reconcile to long-form visible components.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_104_COST_SNAPSHOT_ROW_HASH','COST_SNAPSHOT_ROW_HASH',(SELECT count(*)::text FROM _m1_16_vrow_mismatches WHERE entity_type='COST_SNAPSHOT'),'0',(SELECT count(*)=0 FROM _m1_16_vrow_mismatches WHERE entity_type='COST_SNAPSHOT'),'Cost snapshot row hashes reconstruct physically.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_105_COMPONENT_ROW_HASH','COMPONENT_ROW_HASH',(SELECT count(*)::text FROM _m1_16_vrow_mismatches WHERE entity_type='COMPONENT'),'0',(SELECT count(*)=0 FROM _m1_16_vrow_mismatches WHERE entity_type='COMPONENT'),'Component row hashes reconstruct physically.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_106_ALL_OTHER_PHYSICAL_ROW_HASHES','ALL_OTHER_PHYSICAL_ROW_HASHES',(SELECT count(*)::text FROM _m1_16_vrow_mismatches WHERE entity_type NOT IN('ATTRIBUTION','COST_SNAPSHOT','COMPONENT')),'0',(SELECT count(*)=0 FROM _m1_16_vrow_mismatches WHERE entity_type NOT IN('ATTRIBUTION','COST_SNAPSHOT','COMPONENT')),'Source, campaign, funnel, ledger, touchpoint, latest, and registry hashes reconstruct physically.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_107_LATEST_ARCHIVE_REPRODUCTION','LATEST_ARCHIVE_REPRODUCTION',(SELECT count(*)::text FROM _m1_16_varchive_mismatches),'0',(SELECT count(*)=0 FROM _m1_16_varchive_mismatches),'Immutable archive exactly reproduces latest contract payloads and hashes.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_108_ALL_SET_HASHES_RECONCILE','ALL_SET_HASHES_RECONCILE',(SELECT count(*)::text FROM _m1_16_vctx c CROSS JOIN _m1_16_vhashes h WHERE c.source_profile_set_hash IS DISTINCT FROM h.source_hash OR c.campaign_set_hash IS DISTINCT FROM h.campaign_hash OR c.funnel_set_hash IS DISTINCT FROM h.funnel_hash OR c.cost_ledger_set_hash IS DISTINCT FROM h.ledger_hash OR c.touchpoint_set_hash IS DISTINCT FROM h.touch_hash OR c.attribution_set_hash IS DISTINCT FROM h.attribution_hash OR c.cost_snapshot_set_hash IS DISTINCT FROM h.cost_hash OR c.component_set_hash IS DISTINCT FROM h.component_hash OR c.latest_set_hash IS DISTINCT FROM h.latest_hash OR c.archive_set_hash IS DISTINCT FROM h.archive_hash OR c.contract_set_hash IS DISTINCT FROM h.contract_hash),'0',(SELECT count(*)=0 FROM _m1_16_vctx c CROSS JOIN _m1_16_vhashes h WHERE c.source_profile_set_hash IS DISTINCT FROM h.source_hash OR c.campaign_set_hash IS DISTINCT FROM h.campaign_hash OR c.funnel_set_hash IS DISTINCT FROM h.funnel_hash OR c.cost_ledger_set_hash IS DISTINCT FROM h.ledger_hash OR c.touchpoint_set_hash IS DISTINCT FROM h.touch_hash OR c.attribution_set_hash IS DISTINCT FROM h.attribution_hash OR c.cost_snapshot_set_hash IS DISTINCT FROM h.cost_hash OR c.component_set_hash IS DISTINCT FROM h.component_hash OR c.latest_set_hash IS DISTINCT FROM h.latest_hash OR c.archive_set_hash IS DISTINCT FROM h.archive_hash OR c.contract_set_hash IS DISTINCT FROM h.contract_hash),'All ten entity-family and contract set hashes reconcile.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_109_COMBINED_SET_HASH','COMBINED_SET_HASH',(SELECT h.combined_hash FROM _m1_16_vhashes h),'(SELECT combined_set_hash FROM _m1_16_vctx)',(SELECT h.combined_hash=c.combined_set_hash FROM _m1_16_vhashes h CROSS JOIN _m1_16_vctx c),'The complete 13,274-entity hash chain reconciles.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_110_INTEGRATED_SCENARIO_INVARIANCE','INTEGRATED_SCENARIO_INVARIANCE',(SELECT count(*)::text FROM _m1_16_vscenario WHERE scenario_rows<>2 OR scenario_count<>2 OR source_variants<>1 OR campaign_variants<>1 OR cost_variants<>1),'0',(SELECT count(*)=0 FROM _m1_16_vscenario WHERE scenario_rows<>2 OR scenario_count<>2 OR source_variants<>1 OR campaign_variants<>1 OR cost_variants<>1),'One application-level acquisition contract projects identically into both accepted M1.15 scenarios.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_111_M1_15_PHYSICAL_LATEST_HASH_UNCHANGED','M1_15_PHYSICAL_LATEST_HASH_UNCHANGED',(SELECT md5(string_agg('LATEST|'||scenario_id||'|'||merchant_application_id||'|'||contract_row_hash,'||' ORDER BY scenario_id,merchant_application_id)) FROM msbf_m1.application_module1_latest WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)),'95b54308f082b0fc57be2dd370e94435',(SELECT md5(string_agg('LATEST|'||scenario_id||'|'||merchant_application_id||'|'||contract_row_hash,'||' ORDER BY scenario_id,merchant_application_id))='95b54308f082b0fc57be2dd370e94435' FROM msbf_m1.application_module1_latest WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)),'Accepted M1.15 latest physical population is unchanged.');
  PERFORM pg_temp.m1_16_add_check('M1_16_POS_112_STAGE_BOUNDARY_AND_BLOCKING_ERRORS','STAGE_BOUNDARY_AND_BLOCKING_ERRORS',(SELECT concat_ws('|',(SELECT count(*) FROM msbf_m1.module1_latest WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)),(SELECT count(*) FROM msbf_m1.module1_archive WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)),(SELECT count(*) FROM msbf_ctl.profile_resolution_error WHERE run_id=(SELECT run_id FROM _m1_16_vctx) AND severity='BLOCKING'))),'0|0|0',(SELECT (SELECT count(*) FROM msbf_m1.module1_latest WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx))=0 AND (SELECT count(*) FROM msbf_m1.module1_archive WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx))=0 AND (SELECT count(*) FROM msbf_ctl.profile_resolution_error WHERE run_id=(SELECT run_id FROM _m1_16_vctx) AND severity='BLOCKING')=0),'No legacy output, Module 2 decisioning output, or blocking configuration error exists.');
END;
$checks$;

DO $inventory_guard$
DECLARE v_total bigint;v_pass bigint;v_fail bigint;
BEGIN
 SELECT count(*),count(*) FILTER(WHERE status='PASS'),count(*) FILTER(WHERE status='FAIL')
   INTO v_total,v_pass,v_fail FROM _m1_16_validation;
 IF v_total<>112 THEN RAISE EXCEPTION 'M1.16 expected 112 positive controls; observed %.',v_total; END IF;
END;
$inventory_guard$;

INSERT INTO msbf_ctl.run_evidence(
 run_id,evidence_code,segment_key,metric_name,metric_value_text,unit_code,status,interpretation
)
SELECT (SELECT run_id FROM _m1_16_vctx),evidence_code,'PORTFOLIO',metric_name,
       observed_value,'VALIDATION',status,interpretation
FROM _m1_16_validation
ON CONFLICT(run_id,evidence_code,segment_key) DO UPDATE SET
 metric_name=EXCLUDED.metric_name,metric_value_numeric=NULL,metric_value_text=EXCLUDED.metric_value_text,
 unit_code=EXCLUDED.unit_code,status=EXCLUDED.status,interpretation=EXCLUDED.interpretation,
 created_at=clock_timestamp();

UPDATE msbf_ctl.run_registry
SET run_status=CASE WHEN (SELECT count(*) FROM _m1_16_validation WHERE status='FAIL')=0
                    THEN 'M1_16_VALIDATED' ELSE 'M1_16_FAILED' END,
    notes=coalesce(notes,'')||' | M1.16 positive validation completed.'
WHERE run_id=(SELECT run_id FROM _m1_16_vctx);
UPDATE msbf_ctl.m1_16_acquisition_contract_registry
SET contract_status=CASE WHEN (SELECT count(*) FROM _m1_16_validation WHERE status='FAIL')=0
                         THEN 'VALIDATED' ELSE contract_status END,
    validated_at=CASE WHEN (SELECT count(*) FROM _m1_16_validation WHERE status='FAIL')=0
                      THEN clock_timestamp() ELSE validated_at END
WHERE module1_run_id=(SELECT run_id FROM _m1_16_vctx)
  AND contract_code='M1_ACQUISITION_CONSUMPTION' AND contract_version=1;
COMMIT;
SELECT evidence_code,metric_name,observed_value,threshold_value,status,interpretation
FROM _m1_16_validation ORDER BY evidence_code;
